-- bakone-malapa-open-air-museum-chuenespoort (researched)
UPDATE businesses SET description = 'Bakone Malapa Northern Sotho Open-Air Museum is a living museum near Polokwane, built as a reconstructed village in the style the northern Sotho used about 250 years ago. It shows the daily life of the Bakone, a highly sophisticated subgroup of the northern Sotho, and is one of two similar open-air museums in Limpopo.

Guides demonstrate how fire is made, how maize is ground and how beer is brewed, with two homesteads, or lapas, that display and explain these traditions. Handcraft demonstrations include pottery, basketry and beadwork, and most of the locally made crafts are sold at the village craft shop. The guides are described as excellent storytellers who bring the village''s architecture and culture to life.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.sa-venues.com/attractionslm/bakone-malapa.php'), description_enriched_at = datetime('now') WHERE slug = 'bakone-malapa-open-air-museum-chuenespoort' AND description = 'Bakone Malapa is a reconstructed open-air cultural village near Polokwane depicting traditional Northern Sotho life from roughly 250 years ago, with demonstrations of fire-making, maize grinding, beer brewing, pottery, wood carving, beadwork and basket weaving.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
  AND owner_user_id IS NULL AND COALESCE(subscription_tier, 0) = 0 AND COALESCE(origin, '') != 'owner_submitted'
  AND status = 'published' AND closed_at IS NULL AND is_test = 0
  AND custom_blocks IS NULL AND page_html IS NULL
  AND NOT EXISTS (SELECT 1 FROM business_claims c WHERE c.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM subscriptions s WHERE s.business_id = businesses.id)
  AND NOT EXISTS (SELECT 1 FROM business_photos p WHERE p.business_id = businesses.id);
-- beauty-of-the-bride-polokwane-central (researched)
UPDATE businesses SET description = 'Beauty of the Bride specialises in wedding dresses, with a wide selection from local and international designers at prices the business describes as suitable. Brides can choose to buy or hire their wedding dress, and the website shows standard gowns and new gowns to browse.

The business has been operating for more than nine years and says that finding the right dress is the part of the wedding most brides care about most. Its aim is to help brides look their best on the day and to find an affordable dress that feels like a fairy-tale choice. Each gown on the website has an enquiry option, and visitors can book an appointment online.

Appointments are available on weekdays from 09:00 to 17:00 and on Saturdays from 09:00 to 15:00, with public-holiday visits by appointment only. The shop is based in Polokwane Central.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://beautyofthebride.co.za/'), description_enriched_at = datetime('now') WHERE slug = 'beauty-of-the-bride-polokwane-central' AND description = 'Beauty of the Bride is a bridal boutique in Standard Bank Square offering wedding gowns from local and international designers, available to buy or hire, with an optional wedding-day hair-and-makeup package arranged through partner suppliers.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
