-- biddulphs-international-eduan-park (researched)
UPDATE businesses SET description = 'Biddulphs International''s Polokwane operation is a furniture-removals and relocation business run through the group''s branch network, with the company''s own branch page confirming that its Polokwane service area covers Polokwane, Tzaneen, Mokopane, Louis Trichardt and Lephalale across Limpopo. Rather than running as a fully standalone branch, the Polokwane operation is serviced from the company''s Pretoria branch, reflecting how the national mover organises its regional coverage.

Customers can expect help with household and business moves, including packing assistance for a full home or office relocation, drawing on the group''s century-long history in the removals trade. It serves residential customers, families and organisations relocating within Polokwane and the wider Limpopo region, or further afield through the company''s broader national and international network.', source_urls = json_insert(CASE WHEN json_valid(source_urls) AND json_type(source_urls) = 'array' THEN source_urls ELSE '[]' END, '$[#]', 'https://www.biddulphs.co.za/branches/polokwane', '$[#]', 'https://www.biddulphs.co.za'), description_enriched_at = datetime('now') WHERE slug = 'biddulphs-international-eduan-park' AND description = 'Biddulphs International''s Polokwane branch is a furniture removals and relocation company that also offers self-storage units in a range of sizes, plus palletised and transit storage warehousing, serving Polokwane, Tzaneen and the wider Limpopo region.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
